/**
 * 三個 custom format，全部消費**同一份** style-dictionary token AST
 * （§10.6 ④：不做「先生成 CSS 再字串後處理」的轉換層）。
 *
 *   tokens.css → :root { --gt-* --at-* --ct-* } + [data-theme="…"] { --at-* }
 *   theme.css  → @theme { --color-at-* --color-ct-* --text-* --font-* }（prefix filter 掉 gt）
 *   keys.ts    → 已暴露的 key 清單，給 apps/web 的 cn() 用（§10.3 ⭐）
 */
import type { TransformedToken } from 'style-dictionary/types'

const HEADER = [
  '/**',
  ' * Do not edit directly — generated by `pnpm --filter @stock-life/tokens build`.',
  ' * 唯一真相是 packages/tokens/src/*.tokens.json（DESIGN.md §10.3）。',
  ' */',
].join('\n')

const PURE_REF = /^\{[^{}]+\}$/

/** style-dictionary 的 name/kebab 只做 join('-')，這裡要的是同一套規則。 */
const varName = (path: string[]): string => `--${path.join('-')}`

const refToVar = (ref: string): string => `var(--${ref.slice(1, -1).split('.').join('-')})`

/**
 * 主題 token 掛在 `themes.<name>.at.*` 下，所以它在同一次 build 裡就能解析
 * `{gt.*}` 參照；輸出時把 `themes.<name>` 兩層剝掉還原成 `--at-*`。
 */
const isThemeToken = (token: TransformedToken): boolean => token.path[0] === 'themes'
const themeNameOf = (token: TransformedToken): string => token.path[1]
const aliasPathOf = (token: TransformedToken): string[] => token.path.slice(2)

/**
 * 值的輸出：純參照 → `var(--…)`（讓主題覆寫 alias 層時，下游自動跟著換），
 * 其餘 → 已解析的字面值。
 */
const cssValue = (token: TransformedToken): string => {
  const original: unknown = token.original.$value
  if (typeof original === 'string' && PURE_REF.test(original)) return refToVar(original)
  return String(token.$value)
}

const tokenType = (token: TransformedToken): string | undefined =>
  (token.$type ?? token.original.$type) as string | undefined

const decl = (token: TransformedToken, path = token.path): string =>
  `  ${varName(path)}: ${cssValue(token)};`

// ── tokens.css ──────────────────────────────────────────────────────────────

const TIER_LABEL: Record<string, string> = {
  gt: 'Tier 1 · global —— 原色與原始尺寸。不進 @theme，所以沒有對應 utility',
  at: 'Tier 2 · alias —— 語意層。主題只覆寫這一層',
  ct: 'Tier 3 · component —— 元件專屬，只給 presentation/stage/',
}

export function formatTokensCss(allTokens: TransformedToken[]): string {
  const lines: string[] = [HEADER, '', ':root {']

  for (const tier of ['gt', 'at', 'ct'] as const) {
    const tokens = allTokens.filter((t) => !isThemeToken(t) && t.path[0] === tier)
    if (tokens.length === 0) continue
    lines.push(`  /* ${TIER_LABEL[tier]} */`)
    for (const token of tokens) lines.push(decl(token))
    lines.push('')
  }
  if (lines.at(-1) === '') lines.pop()
  lines.push('}')

  const themeNames = [...new Set(allTokens.filter(isThemeToken).map(themeNameOf))]
  for (const name of themeNames) {
    lines.push('', `[data-theme="${name}"] {`)
    for (const token of allTokens.filter((t) => isThemeToken(t) && themeNameOf(t) === name)) {
      lines.push(decl(token, aliasPathOf(token)))
    }
    lines.push('}')
  }

  return `${lines.join('\n')}\n`
}

// ── theme.css ───────────────────────────────────────────────────────────────

/** Tailwind v4 的 font-size 修飾符命名。 */
const TYPE_FIELD_SUFFIX: Record<string, string> = {
  size: '',
  line_height: '--line-height',
  weight: '--font-weight',
  tracking: '--letter-spacing',
}

interface TypeRoleToken {
  role: string
  field: string
  token: TransformedToken
}

const typeRoleTokens = (allTokens: TransformedToken[]): TypeRoleToken[] =>
  allTokens
    .filter((t) => !isThemeToken(t) && t.path[0] === 'at' && t.path[1] === 'type' && t.path.length === 4)
    .map((token) => ({ role: token.path[2], field: token.path[3], token }))

const fontFamilyTokens = (allTokens: TransformedToken[]): TransformedToken[] =>
  allTokens.filter(
    (t) => !isThemeToken(t) && t.path[0] === 'at' && t.path[1] === 'font' && t.path.length === 3,
  )

const exposedColorTokens = (allTokens: TransformedToken[]): TransformedToken[] =>
  allTokens.filter(
    (t) => !isThemeToken(t) && (t.path[0] === 'at' || t.path[0] === 'ct') && tokenType(t) === 'color',
  )

export function formatThemeCss(allTokens: TransformedToken[]): string {
  const lines: string[] = [
    HEADER,
    '',
    '/* 只有 at + ct 進 @theme。gt 留在 :root 但不生成 utility——',
    '   所以 bg-gt-green-500 這種繞過語意層的寫法「語法上就不存在」（§10.3）。 */',
    '@theme {',
    '  /* colors */',
  ]

  for (const token of exposedColorTokens(allTokens)) {
    lines.push(`  --color-${token.path.join('-')}: var(${varName(token.path)});`)
  }

  const families = fontFamilyTokens(allTokens)
  if (families.length > 0) {
    lines.push('', '  /* font families */')
    for (const token of families) {
      lines.push(`  --font-${token.path[2]}: var(${varName(token.path)});`)
    }
  }

  const roles = typeRoleTokens(allTokens)
  if (roles.length > 0) {
    lines.push('', '  /* semantic type roles：size + line-height + weight 三件一組（§10.5） */')
    for (const { role, field, token } of roles) {
      const suffix = TYPE_FIELD_SUFFIX[field]
      if (suffix === undefined) continue
      lines.push(`  --text-${role}${suffix}: var(${varName(token.path)});`)
    }
  }
  lines.push('}')

  // Tailwind 沒有 font-variant-numeric 的 --text-* 修飾符，所以宣告了
  // variant_numeric 的 role 額外補一條 utility 規則（仍然由 token 驅動）。
  const variants = roles.filter((r) => r.field === 'variant_numeric')
  if (variants.length > 0) {
    lines.push('', '@layer utilities {')
    for (const { role, token } of variants) {
      lines.push(`  .text-${role} {`)
      lines.push(`    font-variant-numeric: var(${varName(token.path)});`)
      lines.push('  }')
    }
    lines.push('}')
  }

  return `${lines.join('\n')}\n`
}

// ── keys.ts ─────────────────────────────────────────────────────────────────

export function formatKeysTs(allTokens: TransformedToken[]): string {
  const colorKeys = exposedColorTokens(allTokens).map((t) => t.path.join('-'))
  const fontKeys = fontFamilyTokens(allTokens).map((t) => t.path[2])
  const roles = [...new Set(typeRoleTokens(allTokens).map((r) => r.role))]
  const themes = ['default', ...new Set(allTokens.filter(isThemeToken).map(themeNameOf))]

  const list = (values: string[]): string =>
    values.length === 0 ? '[]' : `[\n${values.map((v) => `  '${v}',`).join('\n')}\n]`

  return `${HEADER}

/** 進了 @theme 的顏色 key（不含 gt——它刻意沒有 utility）。 */
export const colorKeys = ${list(colorKeys)} as const
export type ColorKey = (typeof colorKeys)[number]

/** semantic type roles（§10.5）。 */
export const typeRoles = ${list(roles)} as const
export type TypeRole = (typeof typeRoles)[number]

/** font-family key。 */
export const fontKeys = ${list(fontKeys)} as const
export type FontKey = (typeof fontKeys)[number]

/** 可用的主題（default 就是 :root，不需要 data-theme）。 */
export const themes = ${list(themes)} as const
export type Theme = (typeof themes)[number]
`
}
